import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const SearchTypeBar: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const f = useCurrentFrame();
  const S = Math.min(frame.width / 1080, frame.height / 1920);
  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const query = String(anim.params?.query ?? anim.text ?? "Pexels Music");
  const eyebrow = String(anim.params?.eyebrow ?? "");
  const hint = String(anim.params?.hint ?? "");

  const barIn = spring({ frame: f, fps, config: { damping: 200, mass: 0.7 } });
  const typeStart = 12;
  const perChar = 2.6;
  const shown = Math.max(0, Math.min(query.length, Math.floor((f - typeStart) / perChar)));
  const typed = query.slice(0, shown);
  const doneAt = typeStart + query.length * perChar;
  const caretOn = f < doneAt ? true : Math.floor((f - doneAt) / 8) % 2 === 0;
  const ring = f > doneAt ? spring({ frame: f - doneAt, fps, config: { damping: 14, mass: 0.6 } }) : 0;

  const fs = Math.min(76, 620 / Math.max(6, query.length * 0.52)) * S;
  const hintOp = interpolate(f, [doneAt + 4, doneAt + 16], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: "84%", display: "flex", flexDirection: "column", alignItems: "center", gap: 40 * S }}>
        {eyebrow ? (
          <div
            style={{
              color: COLORS.teal,
              fontFamily: FONTS.body,
              fontWeight: 600,
              fontSize: 24 * S,
              letterSpacing: 0.22 * 24 * S,
              textTransform: "uppercase",
              textAlign: "center",
              opacity: interpolate(f, [0, 10], [0, 1], { extrapolateRight: "clamp" }),
            }}
          >
            {eyebrow}
          </div>
        ) : null}

        <div style={{ position: "relative", width: "100%" }}>
          <div
            style={{
              position: "absolute",
              inset: -10 * S,
              borderRadius: 999,
              border: `${3 * S}px solid ${COLORS.tealBright}`,
              opacity: ring > 0 ? 1 - ring : 0,
              transform: `scale(${1 + 0.12 * ring})`,
            }}
          />
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 30 * S,
              padding: `${30 * S}px ${44 * S}px`,
              background: COLORS.vellum,
              borderRadius: 999,
              border: `${Math.max(1, 1.5 * S)}px solid rgba(255,255,255,0.12)`,
              boxShadow: "0 24px 60px rgba(0,0,0,0.45)",
              transform: `translateY(${(1 - barIn) * 46 * S}px) scale(${0.95 + 0.05 * barIn})`,
              opacity: barIn,
            }}
          >
            <div style={{ position: "relative", width: 58 * S, height: 58 * S, flex: "0 0 auto" }}>
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  width: 40 * S,
                  height: 40 * S,
                  borderRadius: "50%",
                  border: `${5 * S}px solid ${COLORS.tealBright}`,
                }}
              />
              <div
                style={{
                  position: "absolute",
                  left: 36 * S,
                  top: 36 * S,
                  width: 22 * S,
                  height: 5 * S,
                  borderRadius: 999,
                  background: COLORS.tealBright,
                  transform: "rotate(45deg)",
                  transformOrigin: "left center",
                }}
              />
            </div>

            <div style={{ display: "flex", alignItems: "center", gap: 10 * S, flex: 1, minWidth: 0 }}>
              <span
                style={{
                  fontFamily: FONTS.display,
                  fontWeight: FONTS.displayWeight,
                  textTransform: "uppercase",
                  fontSize: fs,
                  lineHeight: 1.05,
                  backgroundImage: headlineGradient(),
                  WebkitBackgroundClip: "text",
                  backgroundClip: "text",
                  color: "transparent",
                  whiteSpace: "pre-wrap",
                }}
              >
                {typed}
              </span>
              <div
                style={{
                  width: 6 * S,
                  height: fs * 0.86,
                  borderRadius: 3 * S,
                  background: COLORS.tealBright,
                  opacity: caretOn ? 1 : 0,
                }}
              />
            </div>
          </div>
        </div>

        {hint ? (
          <div
            style={{
              color: muted,
              fontFamily: FONTS.mono,
              fontSize: 24 * S,
              letterSpacing: 0.12 * 24 * S,
              textTransform: "uppercase",
              textAlign: "center",
              opacity: hintOp,
              textShadow: ENGRAVE_SHADOW,
            }}
          >
            {hint}
          </div>
        ) : null}

        <div style={{ color: txt, opacity: 0, height: 0 }} />
      </div>
    </AbsoluteFill>
  );
};

export default SearchTypeBar;
